const cards = $input.all().map(item => item.json);

const PROCESSING_LABEL_ID = '69e72e4817206131923d4fcc';
const UPLOADED_LABEL_ID = '69eb6348d13470a412a6ab9b';
const MANUAL_REVIEW_LABEL_ID = '69ecda6ec3c70150828ccc15';
const DESIGN_ISSUE_LABEL_ID = '69ecfa31a36fbbc35b69e217';
const QC_VERIFIED_LABEL_ID = '69471d255442a0100e28a93f';
const QC_FAILED_LABEL_ID = '69471d337a802712e1c8d56c';
const MAX_RETRIES = 3;
const GENERATED_REGEX = /^Mockup\d{2}\.jpg$/;
const TABLETOP_REGEX = /^(?:Tabletop|Tischgeraet|Tischgerät)(?:\d+)?(?:_ai_\d+)?\.(?:jpe?g|png|webp)$/i;
function attachmentTime(a) {
  const raw = a && (a.date || a.createdAt);
  const parsed = raw ? Date.parse(raw) : NaN;
  if (Number.isFinite(parsed)) return parsed;
  const id = String((a && a.id) || '');
  if (/^[0-9a-fA-F]{8}/.test(id)) return parseInt(id.slice(0, 8), 16) * 1000;
  return 0;
}
function generatedSlotNumbers(attachments, minTime = 0) {
  return [...new Set((attachments || []).map(a => {
    if (attachmentTime(a) < minTime) return null;
    const m = (a.name || '').match(/^Mockup(\d{2})\.jpg$/);
    return m ? parseInt(m[1], 10) : null;
  }).filter(n => n !== null))].sort((a, b) => a - b);
}
const BROKEN_REGEX    = /^Mockup(undefined|NaN|null)\.jpg$/i;
// Source-Bilder: neue KI-Mockup-Spalte nutzt image.png; legacy Browser-Mockups bleiben erlaubt.
const SOURCE_REGEX    = /^(image\.png|mockup[\d_.]+\.jpe?g)$/i;
const TARGET_GENERATED_MOCKUPS = 4;
const MAX_PER_RUN = TARGET_GENERATED_MOCKUPS;
const BACKBOARD_FIELD_IDS = {
  1: '67ab333359b643271da233e1',
  2: '67ab333c476749520e9e31ec',
  3: '67f4fac25f71afb659744bce',
  4: '67f4fb1601e710fe13ee8f23',
};

function extractSourceNum(name) {
  if (/^image\.png$/i.test(name || '')) return 999999;
  const m = (name || '').match(/^mockup([\d_.]+)\.jpe?g$/i);
  if (!m) return -1;
  const digits = m[1].replace(/[^\d]/g, '');
  return digits ? parseInt(digits, 10) : -1;
}

function canonicalSignType(text) {
  const lower = (text || '').toLowerCase();
  // NEONTRIP PRODUCT CONTRACT v1: an explicit non-lit title must win over generic neon wording elsewhere.
  if (/\b(?:3d\s*)?(?:non[-\s]?lit|unbeleuchtet|nicht\s*beleuchtet|ohne\s*(?:beleuchtung|licht))\b/.test(lower)) return '3D Non-Lit';
  if (/\b3d\s*frontlit\b/.test(lower)) return '3D Frontlit';
  if (/\b3d\s*backlit\b/.test(lower)) return '3D Backlit';
  if (/\b3d\s*halo\b/.test(lower)) return '3D Halo';
  if (/\b3d\b/.test(lower)) return '3D Leuchtbuchstaben';
  if (/\bhalo\s*lit\b/.test(lower) || /\bhalo\b/.test(lower)) return 'Halo Lit';
  if (/\bdouble\s*sided\b/.test(lower) || /\bnasenschild\b/.test(lower)) return 'Double Sided Lightbox';
  if (/\blight\s*box\b/.test(lower) || /\blightbox\b/.test(lower) || /\bleuchtkasten\b/.test(lower)) return 'Lightbox';
  if (/\bacrylic\b/.test(lower)) return 'Acrylic LED';
  if (/\bfull\s*glow\b/.test(lower)) return 'Full Glow LED Flex';
  if (/\bfront\s*glow\b/.test(lower)) return 'Front Glow LED Flex';
  if (/\bback\s*glow\b/.test(lower)) return 'Back Glow LED Flex';
  if (/\bled\s*flex\b/.test(lower) || /\bneon\s*flex\b/.test(lower)) return 'LED Flex';
  if (/\bled\b/.test(lower) || /\bneon\b/.test(lower)) return 'LED Neon';
  return null;
}

function extractModifiers(text) {
  const lower = (text || '').toLowerCase();
  const mods = [];
  if (/\buv[-\s]?print\b/.test(lower)) mods.push('UV_PRINT');
  if (/\bcut\s*to\s*shape\b/.test(lower)) mods.push('CUT_TO_SHAPE');
  if (/\bloose\s*letters?\b/.test(lower) || /\blose\s*buchstaben\b/.test(lower)) mods.push('LOOSE_LETTERS');
  if (/\bon\s*backboard\b/.test(lower) || /\bauf\s*backboard\b/.test(lower)) mods.push('BACKBOARD');
  return mods;
}


function customFieldTextById(customFields, id) {
  const field = (customFields || []).find(item => item && item.idCustomField === id);
  return field && field.value ? String(field.value.text || field.value.name || field.value.value || '').trim() : '';
}

function customFieldTextValues(customFields) {
  return (customFields || [])
    .map(field => field && field.value ? (field.value.text || field.value.name || field.value.value || '') : '')
    .map(value => String(value || '').trim())
    .filter(Boolean);
}

function normalizeBackboardText(value) {
  return String(value || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/ß/g, 'ss')
    .trim();
}

function extractBackboardValue(card, customFields) {
  const values = customFieldTextValues(customFields);
  const explicit = values.find(value => /einzelne\s+buchstaben|loose\s+letters?|individual\s+letters?|ohne\s+(?:rueckplatte|ruckplatte|backboard|platte)|no\s+(?:backboard|backing\s*plate|backplate)|feinschnitt|formzuschnitt|rechteck|rectang|square|quadratisch|viereck|kontur|contour|cut\s*to\s*shape|cut-to-shape|shape\s*cut|rueckplatte|ruckplatte|backboard|backing\s*plate|backplate|platte/i.test(value));
  if (explicit) return explicit;
  const desc = String((card && card.desc) || '');
  const match = desc.match(/(?:Rueckplatte|Rückplatte|Backboard|Zuschnitt)\s*:\s*([^\n]+)/i);
  return match ? String(match[1] || '').trim() : '';
}

function buildBackboardPromptBlock(backboardValue) {
  const normalized = normalizeBackboardText(backboardValue);
  if (/uv[-\s]?print|uv\s*druck|mit\s+uv\s*druck/i.test(normalized)) {
    return 'NEONTRIP UV-PRINT BACKBOARD CONTRACT v2 - AUTHORITATIVE:\n'
      + 'The explicit UV-Print request overrides every generic clear/transparent acrylic rule.\n'
      + 'Preserve the exact source backboard silhouette, material, opacity and color.\n'
      + 'The UV-printed backing is one continuous solid opaque panel, never transparent or clear acrylic.\n'
      + 'If the source panel is black, keep the complete area inside its outer contour solid opaque black; never show the wall, window or scene through it.\n'
      + 'Only separate LED/neon lines mounted above the UV print may glow. The print and backing panel stay flat and non-illuminated.';
  }
  if (!normalized || /einzelne\s+buchstaben|loose\s+letters?|individual\s+letters?|ohne\s+(?:ruckplatte|rueckplatte|backboard|platte)|no\s+(?:backboard|backing\s*plate|backplate)/i.test(normalized)) {
    return '3D BACKBOARD / RUECKPLATTE - EINZELNE BUCHSTABEN (DEFAULT):\n'
      + 'For 3D frontlit, backlit, halo and non-lit signs the default is individual loose letters without any backing plate.\n'
      + 'If Backboard is empty or says Einzelne Buchstaben / loose letters, render separate stainless steel/acrylic letters mounted directly to the wall.\n'
      + 'Do not render a rectangular plate, contour-cut acrylic panel, shared transparent sheet, white panel or any visible backboard.\n'
      + 'The wall must remain visible in the gaps between all letters and logo elements; only discreet hidden mounting or tiny standoffs are allowed.';
  }
  if (/rechteck|rectang|square|quadratisch|viereck/i.test(normalized)) {
    return '3D BACKBOARD / RUECKPLATTE - EXPLICIT RECTANGULAR PLATE:\n'
      + 'The Trello Backboard field explicitly says: ' + String(backboardValue || '').trim() + '.\n'
      + 'Render the 3D letters mounted on one clean rectangular/square backing plate exactly matching that request.\n'
      + 'If it says white backing plate, the plate must be white. Do not replace it with transparent acrylic or loose letters.';
  }
  return '3D BACKBOARD / RUECKPLATTE - EXPLICIT BACKBOARD:\n'
    + 'The Trello Backboard field explicitly says: ' + String(backboardValue || '').trim() + '.\n'
    + 'Render the requested backing plate/backboard exactly; do not omit it, change its color, or turn it into loose letters.';
}

function extractDesignText(name) {
  const text = String(name || '');
  const matches = [...text.matchAll(/·\s*Design:\s*([^·]+)/giu)]
    .map(match => String(match[1] || '').trim())
    .filter(Boolean);
  return matches.length ? matches[matches.length - 1].slice(0, 300) : '';
}

function stripTitlePrefixes(name) {
  let cur = name || '';
  let prev = null;
  while (cur !== prev) {
    prev = cur;
    // Step 1: ALLE trailing "· Design: …" Suffixe ZUERST entfernen (auch Doppel-Append).
    cur = cur.replace(/\s*·\s*Design:\s*[^·]+$/u, '').replace(/\s+$/, '');
    // Step 2: Leading Status-Marker
    cur = cur.replace(/^[\s\u{1F501}\u{2705}\u{FE0F}]+/u, '');
    cur = cur.replace(/^\s*AI MOCKUP FEHLER\s*(\[\d+\/3\])?[^·\-]*[·\-]\s*/i, '');
    cur = cur.replace(/^\s*❌\s*(\[\d+\/3\])?[^·]*·\s*/, '');
    cur = cur.replace(/^\s*⏸️[^·]*·\s*/, '');
    cur = cur.replace(/^\s*⚠️\s*MOCKUP\s*PRÜFEN[^·]*·\s*/i, '');
    cur = cur.replace(/^\s*🎨\s*DESIGN\s*ABWEICHUNG[^·]*·\s*/i, '');
  }
  return cur;
}

const alreadyProcessingCard = cards.find(card =>
  (card.labels || []).some(label => label.id === PROCESSING_LABEL_ID)
);
if (alreadyProcessingCard) {
  return [];
}

const validCards = [];
let firstInvalid = null;

for (const card of cards) {
  const labels = card.labels || [];
  const labelIds = labels.map(l => l.id);
  const labelNames = labels.map(l => (l.name || '').toLowerCase());
  const hasRetryLabel = labelNames.includes('retry') || labelNames.some(n => n.includes('video generieren'));

  const attachments = card.attachments || [];
  const TABLETOP_TARGET_COUNT = 1;
  const existingTabletopMockups = attachments.filter(a => a.name && TABLETOP_REGEX.test(a.name));
  const existingTabletopNames = new Set(existingTabletopMockups.map(a => String(a.name || '').toLowerCase()));
  const missingTabletopNumbers = [];
  for (let tabletopNumber = 1; tabletopNumber <= TABLETOP_TARGET_COUNT; tabletopNumber++) {
    const expectedName = 'Tabletop' + String(tabletopNumber).padStart(2, '0') + '.png';
    if (!existingTabletopNames.has(expectedName.toLowerCase())) missingTabletopNumbers.push(tabletopNumber);
  }
  const needsTabletopMockup = missingTabletopNumbers.length > 0;
  const terminalMockupLabelPresent =
    labelIds.includes(UPLOADED_LABEL_ID) ||
    labelIds.includes(MANUAL_REVIEW_LABEL_ID) ||
    labelIds.includes(DESIGN_ISSUE_LABEL_ID) ||
    labelIds.includes(QC_VERIFIED_LABEL_ID) ||
    labelIds.includes(QC_FAILED_LABEL_ID);

  // Prevent scheduled backfill loops: once a card is marked uploaded/review/design-issue,
  // do not regenerate only because a later optional tabletop slot is missing.
  // A human can still force a rerun by adding the Retry / Video generieren label.
  if (labelIds.includes(PROCESSING_LABEL_ID)) continue;
  if (terminalMockupLabelPresent && !hasRetryLabel) continue;

  if (attachments.some(a => a.name && BROKEN_REGEX.test(a.name))) {
    if (!firstInvalid) {
      firstInvalid = { json: {
        valid: false, needsAI: false,
        cardId: card.id, cardName: card.name, cardUrl: card.url,
        errorReason: 'Mockupundefined.jpg gefunden — manuell aufräumen nötig'
      } };
    }
    continue;
  }

  const allSourceFiles = attachments.filter(a => a.name && SOURCE_REGEX.test(a.name));
  const totalSourceFiles = allSourceFiles.length;

  const sourceMockups = attachments
    .filter(a =>
      a.name && a.mimeType && a.mimeType.startsWith('image/') &&
      SOURCE_REGEX.test(a.name) &&
      (hasRetryLabel || !GENERATED_REGEX.test(a.name))
    )
    .sort((a, b) => {
      const diff = extractSourceNum(b.name) - extractSourceNum(a.name);
      if (diff !== 0) return diff;
      const timeDiff = attachmentTime(b) - attachmentTime(a);
      if (timeDiff !== 0) return timeDiff;
      return (b.id || '').localeCompare(a.id || '');
    });
  if (sourceMockups.length === 0) continue;

  const chosenSource = sourceMockups[0];
  const chosenSourceTime = attachmentTime(chosenSource);
  const allGeneratedMockups = attachments.filter(a => a.name && GENERATED_REGEX.test(a.name));
  const generatedMockups = allGeneratedMockups.filter(a => hasRetryLabel || attachmentTime(a) >= chosenSourceTime);
  const staleGeneratedMockups = allGeneratedMockups.filter(a => !hasRetryLabel && attachmentTime(a) < chosenSourceTime);
  // Retry fills missing deterministic slots only. Existing slots stay untouched to prevent duplicate images.
  const existingSlotNumbers = generatedSlotNumbers(attachments, chosenSourceTime);
  const currentGenerated = existingSlotNumbers.length;
  if (labelIds.includes(UPLOADED_LABEL_ID) && !hasRetryLabel) continue;

  const titleRaw = card.name || '';
  const designText = extractDesignText(titleRaw);
  const titleStripped = titleRaw.replace(/^[\s\u{1F501}\u{2705}\u{FE0F}]+/u, '');
  const hasErrorMarker = titleStripped.includes('AI MOCKUP FEHLER') || /^\s*❌/.test(titleStripped);
  const hasWaitingMarker = /^\s*⏸️/.test(titleStripped);

  const retryMatch = titleRaw.match(/\[(\d+)\/3\]/);
  const retryCount = retryMatch ? parseInt(retryMatch[1], 10) : (hasErrorMarker ? 1 : 0);
  if (!hasRetryLabel && retryCount >= MAX_RETRIES) continue;

  if ((hasErrorMarker || hasWaitingMarker) && !hasRetryLabel) continue;

  let cardName = stripTitlePrefixes(titleRaw);
  cardName = cardName.replace(/[\u{1F501}]\s*/gu, '').trim();
  if (!cardName) cardName = titleRaw;

  const cardDesc = card.desc || '';

  let signType = canonicalSignType(cardName) || 'LED Neon Sign';
  const modifiers = extractModifiers(cardName);

  const promptHints = [];
  if (signType === '3D Non-Lit') promptHints.push("NON-LIT / UNBELEUCHTET - HIGHEST PRIORITY PRODUCT CONTRACT: This sign has no lighting components and must remain completely unilluminated in every generated variation. No LED or neon-tube appearance, no emitted light, no halo, no glow, no backlighting and no illuminated face. Show only solid 3D material, natural daylight reflections and physically plausible contact shadows. Even if the source rendering looks bright, never interpret brightness as illumination.");
  promptHints.push('FARBIGER UV-DRUCK ERHALTEN: Farbige flächige Druckelemente im Design, auch gelb/rot/blau/grün und auch hinter, unter, zwischen oder um Buchstaben, sind sichtbarer UV-Druck. Diese Flächen exakt übernehmen: flach gedruckt, nicht leuchtend, nicht als Rückplatte/Hintergrund behandeln und nicht entfernen.');
  promptHints.push('TECHNISCHE HILFSLINIEN / ROTE TRENNLINIEN: Wenn eine rote Linie das Design teilt oder durch das Design läuft, ist sie eine technische Markierung. Diese rote Linie NICHT im Mockup zeigen, NICHT leuchten lassen und NICHT als Kontur, Naht, Schnittkante oder Designelement übernehmen. UV-Druck unten plus LED-Neonstreifen darüber als zwei Ebenen behandeln: UV-Druck flach/nicht leuchtend, Neonstreifen oben separat leuchtend.');
  if (modifiers.includes('UV_PRINT')) promptHints.push("NEONTRIP UV-PRINT BACKBOARD CONTRACT v2 - HIGHEST PRIORITY: The explicit UV-Print request overrides every generic transparent-acrylic or cut-to-shape rule that appears anywhere else in the prompt. Preserve the exact backboard silhouette, material, opacity and color visible in the source mockup. The UV-printed backing is one continuous solid opaque panel, not clear acrylic and not an open frame. If the source backboard is black, every pixel inside its visible outer contour that is black in the source must remain solid opaque black in every generated view; the wall or scene must never be visible through that black area. Only the separate LED/neon lines mounted above the print may emit light. UV-printed artwork and the black panel remain flat, non-transparent and non-illuminated.");
  if (modifiers.includes('CUT_TO_SHAPE')) promptHints.push('CUT-TO-SHAPE: Das Schild ist entlang der Design-Kontur ausgeschnitten (keine rechteckige Platte, die Aussenkontur folgt dem Design). Behalte die Schnittkante wie im Originalbild.');
  if (modifiers.includes('LOOSE_LETTERS')) promptHints.push('LOOSE LETTERS: Einzelne Buchstaben, keine Backboard/Platte dahinter. Zwischen den Buchstaben sieht man die Wand. Abstände wie im Originalbild erhalten.');
  if (modifiers.includes('BACKBOARD')) promptHints.push('BACKBOARD: Das Schild hat eine sichtbare Rückplatte / Trägerplatte. Form und Grösse wie im Originalbild.');

  const numToGenerate = Math.min(MAX_PER_RUN, Math.max(0, TARGET_GENERATED_MOCKUPS - currentGenerated));

  if (numToGenerate === 0 && !needsTabletopMockup) {
    if (!firstInvalid && currentGenerated >= TARGET_GENERATED_MOCKUPS) {
      firstInvalid = { json: {
        valid: false, needsAI: false,
        cardId: card.id, cardName, cardUrl: card.url,
        errorReason: 'TARGET_GENERATED_MOCKUPS_REACHED',
        limitReached: true
      } };
    }
    continue;
  }

  let slotsToProcess = [];
  let slotNum = 1;
  while (slotsToProcess.length < numToGenerate && slotNum < 100) {
    if (!existingSlotNumbers.includes(slotNum)) {
      slotsToProcess.push({ slot: slotNum, source: chosenSource });
    }
    slotNum++;
  }

  if (slotsToProcess.length === 0 && !needsTabletopMockup) continue;

  const ioMatch = cardDesc.match(/Indoor\/Outdoor:\s*(Indoor|Outdoor)/i);
  let parsedUsage = '';
  if (ioMatch) parsedUsage = ioMatch[1].toLowerCase() === 'indoor' ? 'Innen' : 'Außen';

  const customFields = card.customFieldItems || [];
  const requestIdField = customFields.find(f => f.idCustomField === '67a200bd23b1ffd304e63335');
  const requestId = requestIdField && requestIdField.value ? (requestIdField.value.text || '') : '';
  const usageField = customFields.find(f => f.idCustomField === '67b714e5a7b5e806684eb8be');
  const descField = customFields.find(f => f.idCustomField === '699d986489ebd38030a0d1eb');
  const backboard = extractBackboardValue(card, customFields);
  const backboardPromptBlock = buildBackboardPromptBlock(backboard);
  const backboardsByIndex = {};
  for (const [index, fieldId] of Object.entries(BACKBOARD_FIELD_IDS)) {
    const value = customFieldTextById(customFields, fieldId);
    if (value) backboardsByIndex[Number(index)] = value;
  }
  if (backboardPromptBlock) promptHints.push(backboardPromptBlock);

  let usage = (usageField && usageField.value ? usageField.value.text : '') || parsedUsage;
  const usageNorm0 = usage.toLowerCase().trim();
  if (usageNorm0 === 'indoor') usage = 'Innen';
  else if (usageNorm0 === 'outdoor') usage = 'Außen';
  const description = descField && descField.value ? (descField.value.text || '') : '';

  const errors = [];
  const usageLower = usage.toLowerCase().trim();
  if (!usageLower || (usageLower !== 'innen' && usageLower !== 'außen' && usageLower !== 'aussen')) errors.push('Usage fehlt');
  const descriptionMissing = !description || description.trim().length < 3;

  if (descriptionMissing && errors.length === 0) {
    if (!firstInvalid) {
      firstInvalid = { json: {
        valid: false, needsAI: true,
        cardId: card.id, cardName, cardUrl: card.url, cardDesc,
        usage: usage.trim(), parsedUsage, requestId,
        signType
      } };
    }
    continue;
  }
  if (descriptionMissing) errors.push('Description fehlt');
  if (errors.length > 0) {
    if (!firstInvalid) firstInvalid = { json: { valid: false, needsAI: false, cardId: card.id, cardName, cardUrl: card.url, errorReason: errors.join('; ') } };
    continue;
  }

  let slotPlans = slotsToProcess.map(p => {
    const fn = p.source.fileName || p.source.name;
    const planBackboard = backboardsByIndex[1] || backboard;
    const planBackboardPromptBlock = buildBackboardPromptBlock(planBackboard);
    return {
      slot: p.slot,
      sourceDownloadUrl: 'https://api.trello.com/1/cards/' + card.id + '/attachments/' + p.source.id + '/download/' + fn,
      sourceName: p.source.name,
      sourceId: p.source.id,
      sourceAttachmentTime: attachmentTime(p.source),
      backboard: planBackboard,
      backboardPromptBlock: planBackboardPromptBlock,
      promptHints: [promptHints.join('\\n\\n'), planBackboardPromptBlock].filter(Boolean).join('\\n\\n'),
    };
  });

  if (needsTabletopMockup) {
    const fn = chosenSource.fileName || chosenSource.name;
    for (const tabletopNumber of missingTabletopNumbers) {
      const tabletopFileName = 'Tabletop' + String(tabletopNumber).padStart(2, '0') + '.png';
      slotPlans.push({
        slot: 9000 + tabletopNumber,
        variantSlot: 98 + tabletopNumber,
        tabletopDevice: true,
        outputFileName: tabletopFileName,
        aiMockupFileName: tabletopFileName,
        sourceDownloadUrl: 'https://api.trello.com/1/cards/' + card.id + '/attachments/' + chosenSource.id + '/download/' + fn,
        sourceName: chosenSource.name,
        sourceId: chosenSource.id,
        sourceAttachmentTime: attachmentTime(chosenSource),
      });
    }
  }

  validCards.push({ json: {
    valid: true,
    cardId: card.id,
    cardName,
    designText,
    cardUrl: card.url,
    cardDesc,
    usage: usage.trim(),
    description: description.trim(),
    backboard,
    backboardPromptBlock,
    signType,
    modifiers,
    promptHints: promptHints.join('\n\n'),
    mockupSlots: slotsToProcess.map(p => p.slot),
    slotPlans,
    totalMockupsNeeded: slotsToProcess.length,
    totalSlotsToProcess: slotPlans.length,
    totalSourceFilesOnCard: totalSourceFiles,
    generatedMockupsOnCard: currentGenerated,
    staleGeneratedMockupsOnCard: staleGeneratedMockups.length,
    activeSourceName: chosenSource.name,
    activeSourceId: chosenSource.id,
    activeSourceAttachmentTime: chosenSourceTime,
    targetGeneratedMockups: TARGET_GENERATED_MOCKUPS,
    hasRetryLabel,
    requestId,
    existingMockups: generatedMockups.map(a => ({ id: a.id, name: a.name })),
    existingTabletopMockups: existingTabletopMockups.map(a => ({ id: a.id, name: a.name })),
    needsTabletopMockup,
    isRetry: hasErrorMarker || hasWaitingMarker,
    retryCount: hasRetryLabel ? 0 : retryCount
  } });
}

if (validCards.length > 0) return [validCards[0]];
if (firstInvalid) return [firstInvalid];
return [];

const prev = $('Extract & Validate').first().json;
const supabaseResult = $input.first().json;

let customerEmail = '';
let companyName = '';

if (Array.isArray(supabaseResult) && supabaseResult.length > 0) {
  customerEmail = supabaseResult[0].email || '';
  if (supabaseResult[0].master_customers) {
    companyName = supabaseResult[0].master_customers.company_name || '';
    if (!customerEmail) customerEmail = supabaseResult[0].master_customers.email || '';
  }
} else if (supabaseResult && supabaseResult.email) {
  customerEmail = supabaseResult.email || '';
}

const emailDomain = customerEmail.includes('@') ? customerEmail.split('@')[1] : '';
const usageText = String(prev.usage || prev.parsedUsage || '').toLowerCase();
const defaultDesc = prev.defaultDesc || (usageText.includes('außen') || usageText.includes('aussen') ? 'Hausfassade' : 'Büro');

return [{ json: {
  cardId: prev.cardId,
  cardName: prev.cardName,
  designText: prev.designText || '',
  cardDesc: prev.cardDesc,
  usage: prev.usage,
  parsedUsage: prev.parsedUsage,
  customerEmail,
  emailDomain,
  companyName,
  defaultDesc,
  forceDefaultDesc: false
} }];

const ctx = $('Build Outlook Search').first().json;
const emailItems = $input.all();

let emailContent = '';
try {
  const emails = emailItems.map(i => i.json);
  if (emails && emails.length > 0 && !emails[0].error) {
    emailContent = emails.map(e => (
      'Betreff: ' + (e.subject || '') + '\nNachricht: ' + (e.bodyPreview || '')
    )).join('\n---\n');
  }
} catch (e) {
  emailContent = '';
}

const allowedSettings = [
