function normalizeText(value) {
  return String(value || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/ä/g, 'ae')
    .replace(/ö/g, 'oe')
    .replace(/ü/g, 'ue')
    .replace(/ß/g, 'ss');
}

function joinedEvidence() {
  return normalizeText([
    ctx.designText,
    ctx.companyName,
    ctx.emailDomain,
    ctx.cardName,
    ctx.cardDesc,
    emailContent
