}

function deterministicSetting() {
  const evidence = joinedEvidence();
  const identity = identityEvidence();
  const design = normalizeText(ctx.designText);
  const usage = normalizeText(ctx.usage || ctx.parsedUsage);

  const has = (pattern) => pattern.test(evidence);
  const identityHas = (pattern) => pattern.test(identity);
  const designHas = (pattern) => pattern.test(design);

  if (identityHas(/\b(sparkasse|volksbank|raiffeisen|bankfiliale|bankhaus|deutsche\s+bank|commerzbank)\b/)) return { setting: 'Bankfiliale', reason: 'strong_bank_identity_keyword' };
  if (has(/\b(fussball|fussballverein|sportverein|vereinsheim|clubheim)\b/) || designHas(/\b(fc|sv|tsv|sc)\s+[a-z0-9]/)) return { setting: 'Vereinsheim', reason: 'sports_club_keyword' };
  if (has(/\b(backerei|baeckerei|backkaffee|brotchen|broetchen|brot|konditorei|backshop)\b/)) return { setting: 'Bäckerei', reason: 'bakery_keyword' };
  if (has(/\b(speakeasy|cocktail|pub|tapasbar|weinbar|bar)\b/)) return { setting: 'Bar', reason: 'bar_keyword' };
  if (has(/\b(cafe|kaffee|espresso|roesterei)\b/)) return { setting: 'Café', reason: 'cafe_keyword' };
  if (has(/\b(restaurant|bistro|pizzeria|grill|imbiss|doener|döner|sushi|kueche|kitchen)\b/)) return { setting: 'Restaurant', reason: 'restaurant_keyword' };
  if (has(/\b(hotel|hostel|ferienwohnung|apartmenthotel)\b/)) return { setting: 'Hotel', reason: 'hotel_keyword' };
  if (has(/\b(zahnarzt|arzt|praxis|physio|therapie|klinik|kosmetikstudio|aesthetik|ästhetik)\b/)) return { setting: 'Praxis', reason: 'practice_keyword' };
  if (has(/\b(friseur|friseur|barber|haarsalon|salon)\b/)) return { setting: 'Friseursalon', reason: 'hair_salon_keyword' };
  if (has(/\b(fitness|gym|yoga|pilates|crossfit|sportstudio)\b/)) return { setting: 'Fitnessstudio', reason: 'fitness_keyword' };
  if (has(/\b(werkstatt|garage|autohaus|carwash|lackiererei)\b/)) return { setting: 'Werkstatt', reason: 'workshop_keyword' };
  if (has(/\b(messe|expo|messestand|booth|ausstellung)\b/)) return { setting: 'Messewand', reason: 'trade_fair_keyword' };
  if (has(/\b(shop|store|laden|boutique|showroom|retail)\b/)) return { setting: 'Ladenlokal', reason: 'retail_keyword' };

  if (usage.includes('aussen') || usage.includes('outdoor')) return { setting: 'Hausfassade', reason: 'outdoor_default' };
  return null;
}

