  const plans = Array.isArray(data.slotPlans) ? data.slotPlans : [];
  const existingMockups = Array.isArray(data.existingMockups) ? data.existingMockups : [];
  const generated = existingMockups.filter(a => a && a.name && GENERATED_REGEX.test(a.name));
  const occupiedSlotNumbers = generatedSlotNumbers(generated);
  const freeSlots = Math.max(0, TARGET_GENERATED_MOCKUPS - occupiedSlotNumbers.length);
  const hasTabletopPlan = plans.some(plan => plan && plan.tabletopDevice === true);

  data.deletedMockups = 0;
  data.deleteErrors = [];
  data.liveCheckFreieSlots = freeSlots;

  if (freeSlots === 0 && !hasTabletopPlan) continue;

  let emitted = 0;
  for (const plan of plans) {
    if (!plan || !plan.sourceDownloadUrl) continue;
    const isTabletop = plan.tabletopDevice === true;
    if (!isTabletop) {
      if (emitted >= freeSlots) continue;
      if (typeof plan.slot !== 'number') continue;
      if (occupiedSlotNumbers.includes(plan.slot)) continue;
      emitted++;
    }

    out.push({
      json: {
        ...data,
        mockupSlot: plan.slot,
        variantSlot: plan.variantSlot || (isTabletop ? 99 : undefined),
        tabletopDevice: isTabletop,
        outputFileName: plan.outputFileName,
        aiMockupFileName: plan.aiMockupFileName,
