  ? totalSlotsToProcess
  : (Number.isFinite(totalMockupsNeeded) && totalMockupsNeeded > 0
    ? totalMockupsNeeded
    : (Array.isArray(extract.mockupSlots) ? extract.mockupSlots.length : 2));
const reqId = extract.requestId || extract.cardId || 'fallback';
const key = 'aggSlots_' + reqId;

sd[key] = (sd[key] || 0) + items.length;

if (sd[key] >= totalNeeded) {
  delete sd[key];
  return [items[0]];
}
return [];

// Parse QC Result mit Retry-Logik bei leerer GPT-4o Response.
// Bei leerer Antwort: bis zu 2 Retries via OpenAI Chat Completions API.
// Wenn alle 3 Versuche leer → contentNotChecked Flag setzen (anderer Comment-Text downstream).

const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const j = item.json || {};

  // Build hat skip gemacht → propagiere direkt
  if (j.skip === true) {
    out.push({ json: { problem: !!j.problem, found: j.found || [], raw: '' }, pairedItem: item.pairedItem });
    continue;
  }

  let text = j?.choices?.[0]?.message?.content
          || j?.candidates?.[0]?.content?.parts?.[0]?.text
          || j?.content?.parts?.[0]?.text
          || j?.text || '';

  // RETRY-LOGIK: Wenn keine Antwort → bis zu 2 Retries
  if (!text) {
    let body = null;
    try {
      const buildOut = $('Build Single-Image QC Body').itemMatching
        ? $('Build Single-Image QC Body').itemMatching(i)
        : $('Build Single-Image QC Body').first();
      body = buildOut?.json?.body || null;
    } catch (e) { /* ignore */ }

    if (body) {
      for (let attempt = 1; attempt <= 2 && !text; attempt++) {
        await new Promise(r => setTimeout(r, 800));
        try {
          const resp = await this.helpers.requestWithAuthentication.call(this, 'openAiApi', {
            method: 'POST',
            url: 'https://api.openai.com/v1/chat/completions',
            body: body,
            json: true
          });
          text = resp?.choices?.[0]?.message?.content || '';
        } catch (e) { /* try next */ }
      }
    }
  }

  // Wenn nach Retries IMMER NOCH leer → contentNotChecked
  if (!text) {
    out.push({
      json: {
        problem: true,
        contentNotChecked: true,
        found: ['OpenAI Vision API antwortete nicht (initial + 2 Retries leer)'],
        raw: ''
      },
      pairedItem: item.pairedItem
    });
    continue;
  }

  // JSON parsen
  let parsed;
  try {
    const clean = String(text).replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();
    parsed = JSON.parse(clean);
  } catch (e) {
    out.push({
      json: { problem: true, found: ['QC parse error: ' + e.message + ' | raw: ' + String(text).slice(0, 200)], raw: text },
      pairedItem: item.pairedItem
    });
    continue;
  }

  out.push({
    json: {
      problem: parsed.problem === true,
      found: Array.isArray(parsed.found) ? parsed.found : [],
      raw: text
    },
    pairedItem: item.pairedItem
  });
}

return out;

// Sichert das Source-Bild-Binary unter eigenem Property-Namen,
