const items = $input.all();
return items.map(item => {
  const j = item.json || {};

  // Build-Step hat bereits geflagged
  if (j.designMismatch === true || j.otherIssues === true) {
    return {
      json: {
        designMismatch: !!j.designMismatch,
        otherIssues: !!j.otherIssues,
        designReasons: Array.isArray(j.designReasons) ? j.designReasons : [],
        otherReasons: Array.isArray(j.otherReasons) ? j.otherReasons : []
      },
      pairedItem: item.pairedItem
    };
  }

  const text = j?.choices?.[0]?.message?.content
            || j?.candidates?.[0]?.content?.parts?.[0]?.text
            || j?.content?.parts?.[0]?.text
            || j?.text || '';

  if (!text) {
    return {
      json: {
        designMismatch: false,
        otherIssues: true,
        designReasons: [],
        otherReasons: ['QC: keine Vision-Antwort — Mail blockiert zur Sicherheit']
      },
      pairedItem: item.pairedItem
    };
  }

  let parsed;
  try {
    const clean = String(text).replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();
    parsed = JSON.parse(clean);
  } catch (e) {
    return {
      json: {
        designMismatch: false,
        otherIssues: true,
        designReasons: [],
        otherReasons: ['QC parse error: ' + e.message]
      },
      pairedItem: item.pairedItem
    };
  }

  return {
    json: {
      designMismatch: parsed.designMismatch === true,
      otherIssues: parsed.otherIssues === true,
      designReasons: Array.isArray(parsed.designReasons) ? parsed.designReasons : [],
      otherReasons: Array.isArray(parsed.otherReasons) ? parsed.otherReasons : []
    },
    pairedItem: item.pairedItem
  };
});

// Holt das Source-Binary aus dem Save Source Binary Node (vor Gemini)
// und fügt es als binary.sourceImage zum aktuellen Item (post-Gemini) hinzu.
// Filesystem-v2 Storage bleibt für die ganze Execution erreichbar.
const items = $input.all();
let sourceItems;
try {
  sourceItems = $('Save Source Binary').all();
} catch (e) {
  sourceItems = [];
}
const out = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const sourceItem = sourceItems[i] || sourceItems[0];
  const sourceJson = (sourceItem && sourceItem.json) || {};
  const sourceBinaryDesc = sourceItem && sourceItem.binary
    ? (sourceItem.binary.sourceImage || sourceItem.binary.data)
    : null;
  const merged = {
    json: { ...sourceJson, ...(item.json || {}) },
    binary: { ...(item.binary || {}) },
    pairedItem: item.pairedItem
  };
  if (sourceBinaryDesc) {
    merged.binary.sourceImage = sourceBinaryDesc;
  }
  out.push(merged);
}
return out;

