const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  if (!item.binary || !item.binary.data) {
    out.push({ json: { skip: true, reason: 'Source-Binary fehlt' }, pairedItem: item.pairedItem });
    continue;
  }
  let buf;
  try {
    buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  } catch (e) {
    out.push({ json: { skip: true, reason: 'Binary nicht lesbar: ' + (e.message || 'unknown') }, pairedItem: item.pairedItem });
    continue;
  }
  const b64 = buf.toString('base64');
  const mime = item.binary.data.mimeType || 'image/jpeg';

  const promptText = `Du analysierst das Source-Bild eines LED-Schild-Designs. Sag mir KURZ was zu sehen ist.\n\nAntwortformat: Genau eine Zeile, beginnend mit "Design: "\nNach "Design: " MAXIMAL 3 WÖRTER.\n\nBeispiele:\n- "Design: Amazon" (bekannte Marke)\n- "Design: Schwarzkopf"\n- "Design: Heinebauer GmbH"\n- "Design: Nautic Club"\n- "Design: OPEN" (Schriftzug erkennbar)\n- "Design: Katze" (Tier/Objekt erkennbar)\n- "Design: Rotes Plus" (Symbol erkennbar)\n- "Design: Unbek. Schriftzug" (Text vorhanden aber nicht zuordenbar)\n- "Design: Unbek. Logo" (Logo-Form aber nicht zuordenbar)\n- "Design: Unbek. Logo + Schriftzug" (beides vorhanden, nicht zuordenbar)\n\nREGELN:\n- MAX 3 Wörter nach "Design: "\n- Bei bekanntem Markennamen → nur Markenname (z.B. "Amazon", NICHT "Amazon Logo")\n- Bei klarem Text → den Text exakt als Schriftzug benennen (z.B. "OPEN", "Nautic Club"); nicht semantisch übersetzen oder als Objekt interpretieren\n- Bei klarem Tier/Objekt → nur dann benennen, wenn das Tier/Objekt als sichtbare Form/Icon im Bild vorhanden ist; Wörter wie "Owl" oder "Crown" allein sind Text, kein Objekt\n- Bei Symbol → kurz beschreiben (z.B. "Rotes Plus")\n- Wenn unklar ob Marke/Text → IMMER abkürzen mit "Unbek." (NICHT "Unbekannt" / "Unbekannter" / "Unbekanntes"): "Unbek. Schriftzug" / "Unbek. Logo" / "Unbek. Logo + Schriftzug"\n- Bei Mischung benutze "+" (NICHT "plus")\n- Bei image.png / technischen Angebotsgrafiken: immer nur das eigentliche Schild-Design auswerten\n- Wenn mehrere Grössen desselben Designs sichtbar sind: bevorzugt das rechte bzw. grösste Design beschreiben\n- Bemassungen, Preise, Zahlen, Breiten/Höhen, Codes, Tabellen, Labels, Pfeile und Spec-Daten KOMPLETT ignorieren\n- Material/Farbe nicht erwähnen wenn nicht nötig (z.B. KEIN "auf Acrylglas")\n- Antworte deutsch`;

  const body = {
    model: 'gpt-4o',
    messages: [
      {
        role: 'user',
        content: [
          { type: 'text', text: promptText },
          { type: 'image_url', image_url: { url: 'data:' + mime + ';base64,' + b64 } }
        ]
      }
    ],
    max_tokens: 30,
    temperature: 0.1
  };

  out.push({ json: { skip: false, body }, pairedItem: item.pairedItem });
}
return out;

const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  if (!item.binary || !item.binary.mockupImage) {
    out.push({ json: { skip: true, problem: false, found: ['QC abort: Mockup-Binary fehlt'] }, pairedItem: item.pairedItem });
    continue;
  }
  let mockupBuf;
  try { mockupBuf = await this.helpers.getBinaryDataBuffer(i, 'mockupImage'); }
  catch (e) {
    out.push({ json: { skip: true, problem: false, found: ['QC: Mockup-Buffer nicht lesbar: ' + (e.message || 'unknown')] }, pairedItem: item.pairedItem });
    continue;
  }
  const b64 = mockupBuf.toString('base64');
  const mime = item.binary.mockupImage.mimeType || 'image/jpeg';

  // NEONTRIP SINGLE-IMAGE PRODUCT CONTRACT v2: never approve the wrong lighting technology or backboard.
  const singleImageProductContext = [
    item.json?.signType,
    item.json?.cardName,
    item.json?.backboard,
    item.json?.promptHints
  ].filter(Boolean).join(' ').toLowerCase();
  const singleImageExpectsNonLit = /non\s*lit|nonlit|unbeleuchtet|nicht\s*beleuchtet|ohne\s*(?:beleuchtung|licht)/i.test(singleImageProductContext);
  const singleImageExpectsOpaqueUvBackboard = /uv[-\s]?print|uv\s*druck|opaque\s*backboard|solid\s+opaque\s+black/i.test(singleImageProductContext);
  const singleImageProductContractRules = [
    'NEONTRIP SINGLE-IMAGE PRODUCT CONTRACT v2 - AUTHORITATIVE:',
    singleImageExpectsNonLit
      ? 'NON-LIT: This sign must be completely unilluminated. Any LED/neon-tube appearance, emitted light, halo, glow, backlighting or illuminated face is a clear problem=true.'
      : 'Lighting must match the explicit product type. Do not approve a different lighting technology.',
    singleImageExpectsOpaqueUvBackboard
      ? 'UV-PRINT: the complete UV-printed panel must be visibly solid and opaque. A transparent/clear/open-frame panel, or background visible through the source-black panel area, is a clear problem=true. Only separate LED/neon lines may glow.'
      : 'STANDARD LED FLEX WITHOUT UV PRINT: follow the explicit backboard contract; do not invent an opaque dark panel.'
  ].join('\n');


  const promptText = `${singleImageProductContractRules}\n\nDu bist QC-Prüfer für ein NEONTRIP Mockup-Bild. Antworte AUSSCHLIESSLICH als JSON.\n\nSchau dir das Mockup an. Flagge problem: true wenn Mockup ENTHÄLT:\n\n1. UNGEWÜNSCHTE TEXTE/ZAHLEN im Bild eingebrannt:\n- Preise, Währungssymbole, Geldbeträge\n- Hersteller-Codes / Artikelnummern (z.B. "GE 0425")\n- Lorem-Ipsum oder Platzhaltertext (z.B. "LOGO HERE")\n- Andere Beschriftungen die nicht Teil des Schild-Designs sind\n\n2. DESIGN-HALLUZINATIONEN:
- Wörter aus dem Schild-Text wurden als Objekt/Icon visualisiert (z.B. "Owl" wird zu Eule, "Crown" wird zu Krone), obwohl dieses Objekt im Source-Design nicht sichtbar war
- Erfundene Tiere, Kronen, Sterne, Pfeile, Rahmen, Ornamente, Logos oder Symbole, die nicht im Source-Bild sichtbar sind
- Schriftzug wurde in ein Bildmotiv umgewandelt statt als exakte Typografie erhalten

3. STRUKTUR-PROBLEME:\n- Mehrere Schilder im Bild statt einem\n- Rückplattenmaterial, -farbe oder -transparenz widerspricht dem SINGLE-IMAGE PRODUCT CONTRACT; bei UV-Print ist eine transparente/klare/offene Rückplatte oder sichtbarer Hintergrund durch die opake Druckfläche immer problem=true
- Eine schwarze/dunkle Rückplatte ist nur ohne expliziten UV-Print-/Backboard-Vertrag ein Problem; bei UV-Print muss die opake Quelle erhalten bleiben
- Falsche Leuchtlogik: ganze Flächen/Rückplatte/Hintergrund leuchten statt nur der helleren LED-/Neon-Streifen
- UV-Druck-Flächen, flache Logos, Illustrationen oder gefüllte Farbflächen leuchten selbst, obwohl nur LED-Neonstreifen leuchten dürfen
- LED-Neonstreifen mit klarer Strichstärke und höherer Helligkeit werden nicht als leuchtende Streifen erkannt
- Rote technische Trennlinien/Hilfslinien aus der Vorlage sind im Mockup sichtbar
- UV-Druck unten und LED-Neonstreifen darüber wurden als eine falsche Ebene vermischt
- NEONTRIP SOURCE BACKBOARD CONTRACT v1: Rückplattenmaterial, -farbe oder -transparenz widerspricht der sichtbaren Quelle oder dem expliziten Produkt-Hinweis; opake und schwarze UV-Druck-Rückplatten sind ausdrücklich zulässig und dürfen nicht als Fehler gelten
- Farbiger UV-Druck, z.B. gelbe/rote/blaue/grüne Druckflächen hinter oder um Buchstaben, fehlt im Mockup oder wurde entfernt
- Farbiger UV-Druck wurde fälschlich als Neon/Glow dargestellt statt flach gedruckt
- Collage/Compilation/Kontaktbogen/Vierer-Raster/Split-Screen oder mehrere separate Fotos/Panels in einem Mockup
- LED-/Neon-Streifen, die in der Vorlage klar heller als der Hintergrund sind, leuchten im Mockup nicht\n- Erfundene Hardware (extra Schrauben, Halterungen, Kabel)\n\nNICHT als problem flaggen:\n- Texte die Teil des Schild-Designs sind ("OPEN", Markennamen, gewollte Logos)\n- Möbel, Wände, Pflanzen im Hintergrund\n- Leuchten/Glow ist nur dann unproblematisch, wenn der SINGLE-IMAGE PRODUCT CONTRACT kein Non-Lit/Unbeleuchtet verlangt\n- WATERMARK / LOGO / DISCLAIMER unten rechts: KOMPLETT IGNORIEREN\n- Reine Bemassungs-Annotationen / Maßangaben in cm (z.B. "100 cm", "52.3 cm", "75x50cm", Pfeil-Linien mit Maßzahlen): KOMPLETT IGNORIEREN, auch wenn sie sichtbar im Mockup sind\n\nAntwortformat (strikt JSON):\n{"problem": true, "found": ["Preis '60€' im Bild sichtbar"]}\noder\n{"problem": false, "found": []}\n\nSchwarze Designbereiche und Rückplatten strikt gemäß SINGLE-IMAGE PRODUCT CONTRACT bewerten: Bei UV-Print bleibt die schwarze Druckplatte opak und nichtleuchtend; ohne UV-Print keine dunkle Platte erfinden. Bei sichtbarer Design-Halluzination streng sein: erfundene Objekte/Symbole sind ein klares Problem. Sei bei unklaren Details sonst NICHT übermässig streng. Halluziniere nichts. Nur klare, eindeutige Probleme melden die WIRKLICH im Bild sind.`;

  const body = {
    model: 'gpt-4o-mini',
    messages: [
      { role: 'user', content: [
        { type: 'text', text: promptText },
        { type: 'image_url', image_url: { url: 'data:' + mime + ';base64,' + b64 } }
      ]}
    ],
    response_format: { type: 'json_object' },
    max_tokens: 2048,
    temperature: 0.1
  };

  out.push({ json: { skip: false, body }, pairedItem: item.pairedItem });
}
return out;

