const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  if (!item.binary?.data) {
    out.push({ json: { skip: true, body: null }, pairedItem: item.pairedItem });
    continue;
  }
  let buf;
  try { buf = await this.helpers.getBinaryDataBuffer(i, 'data'); }
  catch (e) { out.push({ json: { skip: true, body: null }, pairedItem: item.pairedItem }); continue; }
  const b64 = buf.toString('base64');
  const mime = item.binary.data.mimeType || 'image/jpeg';
  const promptText = `Schau dir das eigentliche Schild-Design im Bild an. Bei image.png / technischen Angebotsgrafiken ignoriere Preise, Masse, Zahlen, Codes, Tabellen, Pfeile, Labels und Zusatztexte. Weiße/hellgraue/graue Flächen im image.png sind als Hintergrund/Spec-Sheet zu ignorieren und bedeuten keine weiße oder graue Rückplatte. Die Rückplatte ist transparentes/klares Acryl und darf nicht als Lichtfarbe bewertet werden. Wenn mehrere Grössen desselben Designs sichtbar sind, bewerte bevorzugt das rechte bzw. grösste Design. Bestimme die Lichtfarbe der tatsächlichen LED-/Neon-Streifen selbst (NICHT des Hintergrunds, NICHT der Rückplatte und NICHT von UV-Druck). Die leuchtenden Streifen sind in der technischen Zeichnung immer heller als Hintergrund, Rückplatte oder nicht leuchtende Flächen. UV-Druck ist flach gedruckt und leuchtet nicht. LED-Neonstreifen sind linienartige Streifen/Tubes mit sichtbarer Strichstärke und heller als Hintergrund/Rückplatte/UV-Druck-Flächen. Bewerte für die Lichtfarbe nur diese LED-Neonstreifen. Farbige flächige Druckelemente (z.B. gelbe Formen/Flächen hinter Buchstaben) sind UV-Druck: als Designfarbe erhalten, aber nicht als Lichtfarbe/Glow bewerten. Rote technische Trennlinien/Hilfslinien sind keine Lichtfarbe und kein Designbestandteil. Wenn Designbereiche in der technischen Zeichnung schwarz dargestellt sind, gilt das als KALTWEISS leuchtend, nicht als schwarz.

Antworte AUSSCHLIESSLICH als JSON:
- Schild leuchtet einfarbig KALTWEISS (schneeweiß, ohne Blau- oder Gelbstich) ODER Design ist in der Zeichnung schwarz dargestellt: {"color": "kaltweiß"}
- Schild leuchtet einfarbig WARMWEISS (gelblich, ~3000K): {"color": "warmweiß"}
- Schild leuchtet farbig (rot/blau/grün/etc.) oder mehrfarbig: {"color": "farbig"}
- Wenn nur Hintergrund/Rückplatte/Preise/Masslinien hell sind, aber keine LED-/Neon-Streifen eindeutig erkennbar sind: {"color": "unklar"}
- Bei Unsicherheit: {"color": "unklar"}`;
  const body = {
    model: 'gpt-4o',
    messages: [
      { role: 'user', content: [
        { type: 'text', text: promptText },
        { type: 'image_url', image_url: { url: 'data:' + mime + ';base64,' + b64 } }
      ]}
    ],
    response_format: { type: 'json_object' },
    max_tokens: 50,
    temperature: 0
  };
  out.push({ json: { skip: false, body }, pairedItem: item.pairedItem });
}
return out;

const items = $input.all();
return items.map((item) => {
  const text = item.json?.choices?.[0]?.message?.content || '';
  let color = 'unklar';
  try { color = (JSON.parse(text).color || 'unklar').toLowerCase(); }
  catch (e) { /* default unklar */ }

  let colorBlock;
  if (color === 'kaltweiß' || color === 'kaltweiss') {
    colorBlock = `FARBE (SEHR WICHTIG):
Oberfläche und Licht sind zwei getrennte Ebenen.

- Oberflächenfarbe bleibt exakt wie im Input
- DAS SCHILD MUSS KALTWEISS LEUCHTEN — schneeweißer Schein, KEIN Blaustich, KEIN Gelbstich, rein-neutral-weiß.
- Niemals warmweiß oder gelblich rendern.
- Niemals einen Blaustich/Cyan-Schimmer reininterpretieren.`;
  } else if (color === 'warmweiß' || color === 'warmweiss') {
    colorBlock = `FARBE (SEHR WICHTIG):
Oberfläche und Licht sind zwei getrennte Ebenen.

- Oberflächenfarbe bleibt exakt wie im Input
- DAS SCHILD MUSS WARMWEISS LEUCHTEN — gelblich-warmer Schein bei ~3000K.
- Niemals kaltweiß oder schneeweiß rendern.`;
  } else {
    colorBlock = `FARBE (SEHR WICHTIG):
Oberfläche und Licht sind zwei getrennte Ebenen.

- Oberflächenfarbe bleibt exakt wie im Input
- Lichtfarbe bleibt exakt wie im Input
- NIEMALS Lichtfarbe aus der Oberflächenfarbe ableiten`;
  }

  return { json: { color, colorBlock }, pairedItem: item.pairedItem };
});

// Check ob Variant B Gemini-Fallback benutzt wurde.
// Liest staticData Flag (gesetzt von Prep Gemini Fallback) und räumt es auf.

const sd = $getWorkflowStaticData('global');
let fallbackUsed = false;
let reqId = '';
try {
  const ext = $('Extract & Validate').first().json;
  reqId = ext.requestId || ext.cardId || 'fallback';
  if (sd['fallbackUsed_' + reqId] === true) {
    fallbackUsed = true;
    delete sd['fallbackUsed_' + reqId];
  }
} catch (e) { /* ignore */ }

return $input.all().map(item => ({
  json: { ...(item.json || {}), fallbackUsed, reqId },
  binary: item.binary,
  pairedItem: item.pairedItem
}));

// Reduziert die Items auf genau 1 (das erste).
// Verhindert dass Detection-Chain 4x läuft (= 4x GPT-4o Vision Call) wenn Trello DELETE
// mehrere Labels als Items zurückgibt.

return $input.all().slice(0, 1);

// Compute idempotent design title without Trello secrets.
let extractData = {};
try {
  const ev = $('Extract & Validate').first();
  if (ev && ev.json) extractData = ev.json;
} catch (e) {
  return [{ json: { skip: true, shouldUpdate: false, reason: 'Extract & Validate not executed' } }];
}

const cardId = extractData.cardId;
if (!cardId) {
  return [{ json: { skip: true, shouldUpdate: false, reason: 'Missing cardId' } }];
}

let detectResp = {};
try {
  const dd = $('Detect Design').first();
  if (dd && dd.json) detectResp = dd.json;
} catch (e) {
  return [{ json: { skip: true, shouldUpdate: false, cardId, reason: 'Detect Design not executed' } }];
}

const designText = (detectResp?.choices?.[0]?.message?.content || '').trim();
if (!designText) {
  return [{ json: { skip: true, shouldUpdate: false, cardId, reason: 'No design text from Detect Design' } }];
}

const card = $input.first().json || {};
if (card.error) {
  return [{ json: { skip: true, shouldUpdate: false, cardId, designText, reason: 'GET fail: ' + (card.error.message || card.error.description || 'unknown') } }];
}

let baseName = card.name || '';
{
  let prev = null;
  while (baseName !== prev) {
    prev = baseName;
    baseName = baseName.replace(/s*·s*Design:s*[^·]+$/u, '').replace(/s+$/, '');
  }
}

if (!baseName) {
  return [{ json: { skip: true, shouldUpdate: false, cardId, designText, reason: 'Empty base name', cardNameLive: card.name } }];
}

const newName = baseName + '  ·  ' + designText;
if (card.name === newName) {
  return [{ json: { skip: true, shouldUpdate: false, cardId, newName, designText, previousName: card.name, reason: 'Already set' } }];
}

return [{ json: { skip: false, shouldUpdate: true, cardId, newName, designText, previousName: card.name } }];
